/* ---------- File explorer ---------- */
.fxp{padding:8px;display:flex;flex-direction:column;gap:4px;height:380px}
.fxp-h{display:flex;gap:4px;align-items:center}
.fxp-s{flex:1;display:flex;align-items:center;gap:8px;height:32px;padding:0 10px;border-radius:10px;background:var(--chip);box-shadow:inset 0 0 0 1px var(--field-line);color:var(--muted)}
.fxp-s input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--fg)}
.fxp-s:focus-within{box-shadow:inset 0 0 0 2px var(--focus)}
.fxp-s input::placeholder{color:var(--muted)}
.fxp-tree{flex:1;overflow:auto;padding:4px 0 16px;-webkit-mask-image:linear-gradient(180deg,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(180deg,#000 calc(100% - 28px),transparent)}
/* a thin scrollbar in the style's hairline grey, not the browser's thick one */
.fxp-tree{scrollbar-width:thin;scrollbar-color:var(--rail) transparent}
.fxp-tree::-webkit-scrollbar{width:8px;height:8px}
.fxp-tree::-webkit-scrollbar-track{background:transparent}
.fxp-tree::-webkit-scrollbar-thumb{background:var(--rail);border:2px solid transparent;background-clip:padding-box;border-radius:var(--r-pill)}
:root:not([data-style="soft"]) .fxp-tree:not(:where([data-style="soft"],[data-style="soft"] *))::-webkit-scrollbar-thumb{border-radius:0}
.fxp-n{display:flex;align-items:center;gap:6px;width:100%;height:30px;padding-right:8px;border-radius:8px;font-size:13px;text-align:left;color:var(--fg2);transition:background .15s,color .15s}
@media (hover:hover) and (pointer:fine){.fxp-n:hover{background:var(--row);color:var(--fg)}}
/* rows fill the scrolling tree, which would cut an outside ring: theirs is drawn inside */
.fxp-n:focus-visible{outline-offset:-2px}
.fxp-n.sel{background:var(--sel);color:var(--fg)}
.fxp-n .cv{width:14px;display:grid;place-items:center;color:var(--muted);transition:transform .35s var(--ease)}
.fxp-n.open .cv{transform:rotate(90deg)}
.fxp-n .ic{color:var(--muted);display:grid}
.fxp-n .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fxp-n .bd{font-family:var(--mono);font-size:10.5px;font-weight:500;width:14px;text-align:center}
.fxp-n .bd.M{color:var(--warn)}.fxp-n .bd.A{color:var(--ok)}.fxp-n .bd.D{color:var(--bad)}
.fxp-n.D .nm{text-decoration:line-through;color:var(--muted)}
.fxp-n .ag{width:6px;height:6px;border-radius:50%;background:var(--accent)}
.fxp-k{display:grid;grid-template-rows:1fr;transition:grid-template-rows .4s var(--ease)}
.fxp-k.shut{grid-template-rows:0fr}
.fxp-k>div{overflow:hidden}
.fxp-f{font-size:12px;padding:4px 8px}

DM.def('file-explorer', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search','xs')).replace('{filter}', I('filter','xs'));
  const T = { n:'', k:[
    { n:'src', k:[
      { n:'components', k:[ { n:'PlanCard.tsx', s:'M' }, { n:'PriceTag.tsx', s:'A' }, { n:'Button.tsx' }, { n:'LegacyCTA.tsx', s:'D' } ] },
      { n:'styles', k:[ { n:'tokens.css', s:'M' }, { n:'globals.css' } ] },
      { n:'pages', k:[ { n:'pricing.mdx', s:'M' }, { n:'index.mdx' } ] }
    ]},
    { n:'public', k:[ { n:'og-pricing.png', s:'A' }, { n:'favicon.svg' } ] },
    { n:'package.json' }, { n:'README.md' }
  ]};
  const tree = $('.fxp-tree', r), inp = $('.fxp-s input', r), chB = $('.fxp-ch', r), st = $('.fxp-st', r);
  const open = new Set(['src','src/components','src/styles']); let only = false, sel = 'src/components/PlanCard.tsx';
  const changed = n => n.s || (n.k && n.k.some(changed));
  const match = (n, q) => !q || n.n.toLowerCase().includes(q) || (n.k && n.k.some(k => match(k, q)));
  const ext = n => /\.(tsx)$/.test(n) ? 'code' : /\.css$/.test(n) ? 'palette' : /\.png|\.svg$/.test(n) ? 'image' : 'file-text';
  function build(n, path, d, q){
    return n.k.filter(k => match(k, q) && (!only || changed(k))).map(k => {
      const p = path ? path + '/' + k.n : k.n, isD = !!k.k, op = isD && (open.has(p) || !!q || only);
      return `<button class="fxp-n${isD && op ? ' open' : ''}${p === sel ? ' sel' : ''}${k.s ? ' ' + k.s : ''}" data-p="${p}" ${isD ? 'data-d="1"' : ''} style="padding-left:${6 + d * 14}px" role="treeitem"><span class="cv">${isD ? I('chev-r','xs') : ''}</span><span class="ic">${I(isD ? 'folder' : ext(k.n),'xs')}</span><span class="nm">${k.n}</span>${k.s ? `<span class="bd ${k.s}">${k.s}</span>` : isD && changed(k) ? '<span class="ag"></span>' : ''}</button>` + (isD ? `<div class="fxp-k${op ? '' : ' shut'}"><div>${build(k, p, d + 1, q)}</div></div>` : '');
    }).join('');
  }
  function paint(){
    tree.innerHTML = build(T, '', 0, inp.value.trim().toLowerCase());
    $$('.fxp-n', tree).forEach(b => b.onclick = () => {
      if (b.dataset.d){ const p = b.dataset.p, k = b.nextElementSibling; const o = !open.has(p); o ? open.add(p) : open.delete(p); b.classList.toggle('open', o); k.classList.toggle('shut', !o); }
      else { sel = b.dataset.p; $$('.fxp-n', tree).forEach(x => x.classList.toggle('sel', x === b)); swap(st, sel); }
    });
  }
  inp.oninput = paint;
  chB.onclick = () => { only = !only; chB.classList.toggle('on', only); swap(st, only ? '6 files changed by the agent' : sel); paint(); stagger($$('.fxp-n', tree), 25); };
  st.textContent = sel; paint(); stagger($$('.fxp-n', tree), 25);
});
